r=Path(__file__).resolve().parent;out=r/'results';default=json.loads((out/'default_bridge_comparison.json').read_text());a=json.loads((out/'recovered_optional_comparison.json').read_text());d=np.load(out/'corrected_vendor.npz');raw=default['results']['identity'];cor=default['results']['repo_default'];hy=a['optional_guarded_hybrid'];guard=a['guard'];commit=a['commit'];url='https://github.com/Faheemibrahim/unitree_go2_ros2/blob/'+commit+'/';origin=default['source_seconds_origin_ns'];tt=(d['source_stamp_ns']-origin)/1e9;fig,ax=plt.subplots(1,2,figsize=(13,6),layout='constrained')
